package dht

// DiscoveryService is the interface that blockchain.BlockchainServer expects
type DiscoveryService interface {
	ID() string
	Close()
	Run(interface{})
}

// DiscoveryManager combines DiscoveryService with additional methods
type DiscoveryManager interface {
	DiscoveryService
	AnnounceChain(ctx context.Context, chainID string, multiaddr string) error
	FindChain(ctx context.Context, chainID string) ([]interface{}, error)
}

// DiscoveryClient implements DiscoveryService and DiscoveryManager
type DiscoveryClient struct {
	*Client // Embed the Client for CacheResource methods
}

// Ensure DiscoveryClient implements the interfaces
var _ DiscoveryService = (*DiscoveryClient)(nil)
var _ DiscoveryManager = (*DiscoveryClient)(nil)

// ID returns a placeholder peer ID
func (dc *DiscoveryClient) ID() string {
	return "dht-client-" + dc.source
}

// Close is a no-op for the client
func (dc *DiscoveryClient) Close() {
	// Nothing to close
}

// Run is a no-op for the client
func (dc *DiscoveryClient) Run(interface{}) {
	// Background work happens in KNIRVGATEWAY
}

// AnnounceChain announces a blockchain node via DHT
func (dc *DiscoveryClient) AnnounceChain(ctx context.Context, chainID string, multiaddr string) error {
	return dc.AnnounceChain(ctx, chainID, multiaddr)
}

// FindChain finds blockchain nodes via DHT
func (dc *DiscoveryClient) FindChain(ctx context.Context, chainID string) ([]interface{}, error) {
	peers, err := dc.FindResource(ctx, chainID, "chain")
	if err != nil {
		return nil, err
	}

	result := make([]interface{}, len(peers))
	for i, p := range peers {
		result[i] = p
	}
	return result, nil
}

// NewDiscoveryManager creates a new DiscoveryClient (satisfies p2p.NewDiscoveryManager signature)
func NewDiscoveryManager(chainID string, p2pPort int, clientOnly bool, isBootnode bool, role interface{}, cfg interface{}) (DiscoveryService, error) {
	client := NewDiscoveryClient("/tmp/knirvgateway.sock")
	return &DiscoveryClient{Client: client}, nil
}

// NewP2PConsensusManager creates a stub P2P consensus manager
type P2PConsensusManager struct{}

func (p *P2PConsensusManager) Start() {}
func (p *P2PConsensusManager) Stop() {}

func NewP2PConsensusManager(bc interface{}, db interface{}, dm interface{}, role interface{}) (*P2PConsensusManager, error) {
	return &P2PConsensusManager{}, nil
}

